 function permissionState(){const allowed=form.find('[name="contact_permission_status"]').val()==='ALLOWED';form.find('[name="lawful_basis"], [name="allow_phone"][type="checkbox"], [name="allow_email"][type="checkbox"], [name="allow_line"][type="checkbox"]').prop('disabled',!allowed);if(!allowed)form.find('[name="allow_phone"][type="checkbox"], [name="allow_email"][type="checkbox"], [name="allow_line"][type="checkbox"]').prop('checked',false);}
 function reset(){form[0].reset();form.attr('action',form.data('store-url'));method.val('POST');form.find('[name="is_active"]').prop('checked',true);permissionState();form.find('.is-invalid').removeClass('is-invalid');form.find('.invalid-feedback').text('');}
 form.find('[name="contact_permission_status"]').on('change',permissionState);permissionState();$('.js-new-contact').on('click',reset);$('.js-cancel-contact').on('click',function(){reset();bootstrap.Collapse.getOrCreateInstance(wrap).hide();});
 $('.js-edit-contact').on('click',function(){reset();const button=$(this),contact={name:button.data('name'),position:button.data('position'),decision_role:button.data('decision-role'),phone:button.data('phone'),email:button.data('email'),line_id:button.data('line-id'),preferred_channel:button.data('preferred-channel'),contact_permission_status:button.data('contact-permission-status'),lawful_basis:button.data('lawful-basis'),allow_phone:Number(button.data('allow-phone')),allow_email:Number(button.data('allow-email')),allow_line:Number(button.data('allow-line')),permission_note:button.data('permission-note'),is_primary:Number(button.data('is-primary')),is_active:Number(button.data('is-active')),notes:button.data('notes')};form.attr('action',button.data('url'));method.val('PUT');Object.entries(contact).forEach(function([field,value]){const input=(['is_primary','is_active','allow_phone','allow_email','allow_line'].includes(field))?form.find('[name="'+field+'"][type="checkbox"]'):form.find('[name="'+field+'"]');if(input.attr('type')==='checkbox')input.prop('checked',!!value);else input.val(value||'');});permissionState();bootstrap.Collapse.getOrCreateInstance(wrap).show();wrap.scrollIntoView({behavior:'smooth',block:'start'});});
 form.on('submit',function(event){event.preventDefault();const submit=form.find(':submit');submit.prop('disabled',true);form.find('.is-invalid').removeClass('is-invalid');form.find('.invalid-feedback').text('');$.ajax({url:form.attr('action'),method:'POST',data:form.serialize(),headers:{Accept:'application/json','X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')||''}}).done(function(){location.reload();}).fail(function(xhr){submit.prop('disabled',false);const errors=xhr.responseJSON&&xhr.responseJSON.errors;if(errors){Object.entries(errors).forEach(function([field,messages]){form.find('[name="'+field+'"]').addClass('is-invalid');form.find('[data-error="'+field+'"]').text(messages[0]);});return;}window.erpAjaxError(xhr);});});
 $('.js-delete-contact').on('click',function(){const button=$(this);Swal.fire({icon:'warning',title:'ลบผู้ติดต่อนี้?',text:'ประวัติ Audit Log จะยังคงอยู่',showCancelButton:true,confirmButtonText:'ลบ',cancelButtonText:'กลับ'}).then(function(result){if(!result.isConfirmed)return;button.prop('disabled',true);$.ajax({url:button.data('url'),method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')||''}}).done(function(){location.reload();}).fail(function(xhr){button.prop('disabled',false);window.erpAjaxError(xhr);});});});
});
