 $('.js-delete-customer').on('click',function(){const button=$(this);Swal.fire({icon:'warning',title:'ลบข้อมูลลูกค้า?',text:'ลบได้เฉพาะลูกค้าที่ไม่มี Opportunity หรือเอกสารธุรกิจ ประวัติ Audit Log จะยังคงอยู่',showCancelButton:true,confirmButtonText:'ลบข้อมูลลูกค้า',cancelButtonText:'กลับ'}).then(function(result){if(!result.isConfirmed)return;button.prop('disabled',true);$.ajax({url:button.data('url'),method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')||''}}).done(function(response){location.href=response.redirect;}).fail(function(xhr){button.prop('disabled',false);window.erpAjaxError(xhr);});});});
 const form=$('#timeline-filter'),list=$('#customer-timeline'),pagination=$('#timeline-pagination'),summary=$('#timeline-summary'),dataUrl=@json(route('crm.customers.timeline',$customer));let request;
 function load(page){if(request)request.abort();const params=new URLSearchParams(new FormData(form[0]));if(page>1)params.set('page',page);list.attr('aria-busy','true').html('<div class="text-center text-secondary py-5"><span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>กำลังโหลด Timeline...</div>');pagination.empty();request=$.getJSON(dataUrl,params.toString()).done(function(data){list.html(data.html).attr('aria-busy','false');pagination.html(data.pagination);summary.text(data.total?'แสดง '+data.from+'–'+data.to+' จาก '+Number(data.total).toLocaleString('th-TH')+' เหตุการณ์':'ไม่พบเหตุการณ์');}).fail(function(xhr,status){if(status==='abort')return;list.attr('aria-busy','false').html('<div class="alert alert-danger mb-0">โหลด Timeline ไม่สำเร็จ <button class="btn btn-sm btn-outline-danger ms-2 js-retry-timeline" type="button">ลองใหม่</button></div>');});}
 form.on('submit',function(event){event.preventDefault();load(1);});pagination.on('click','a.page-link',function(event){event.preventDefault();load(Number(new URL(this.href).searchParams.get('page')||1));});list.on('click','.js-retry-timeline',function(){load(1);});load(1);
});
</script>
